static int plane_rows(int fmt, int h, int plane) {
    if (plane == 0) return h;
    switch (fmt) {
        case PIX_YUV420P: case PIX_NV12: case PIX_NV21: return (h + 1) / 2;
        case PIX_YUV422P: case PIX_YUV444P:             return h;
